<script lang="ts">
  import { onMount } from 'svelte';
  import { ArrowRight, Calculator, ChevronRight, Info } from 'lucide-svelte';
  import { cmsStore, fetchCmsContent } from '$lib/cms';
  onMount(() => { fetchCmsContent(); });
  let selectedContract = $state('Semua akad');
