  let deals = $derived(info?.liveDeals || []);
  let contracts = $derived(['Semua akad', ...new Set(deals.map(d => d.contract))]);
  let filteredDeals = $derived(selectedContract === 'Semua akad' ? deals : deals.filter(d => d.contract === selectedContract));
  let tiers = $derived(info?.lenderTiers || []);
  let steps = $derived(info?.steps || []);
  let safety = $derived(info?.safetyMeasures || []);
  let testimonials = $derived(($cmsStore.testimonials || []).filter(t => t.type === 'investor'));
</script>

